#!/usr/bin/env bash
# นิยามว่า "ไฟล์แอป" คืออะไร · นับการแตะ vendor · จับการโหลดของจากเน็ต — ที่เดียวของทั้ง repo
#
# ── ทำไมต้องแยกออกมาเป็นสคริปต์ ──────────────────────────────────
# ตรรกะพวกนี้เคยฝังอยู่ใน YAML ของ workflow ซึ่ง **เทสเรียกไม่ได้**
# วิธียืนยันเดียวที่ทำได้คือสร้าง repo จำลองด้วยมือแล้วรันคำสั่งเทียบ
# ซึ่งพิสูจน์อะไรให้ PR รอบถัดไปไม่ได้เลย เพราะ repo นั้นถูกลบทิ้งหลังตรวจเสร็จ
#
# repo นี้เคยพลาดรูปแบบเดียวกันนี้สี่รอบติดกับด่าน vendor เมื่อ 30 ส.ค. 2026
# จนต้องแยก vendor-gate.sh ออกมา — ไฟล์นี้คือการทำแบบเดียวกันกับด่านที่เหลือ
# เทสอยู่ที่ tests/guard-app-files.test.sh และ CI รันทุก PR
#
# ⚠️ PR ที่แก้ไฟล์นี้ = PR ที่แก้ด่านตรวจเอง · agent-guard ข้อ 1 จะตะโกนให้เจ้าของอ่านด้วยตา
#
# ใช้งาน:  source .github/scripts/app-files.sh   แล้วเรียกฟังก์ชันโดยส่ง base branch เข้าไป
#          เช่น  app_changed_files origin/main

set -uo pipefail

# ── นิยามของ "ไฟล์แอป" ─────────────────────────────────────────────
# .html และ .js ทุกไฟล์ ยกเว้นสามอย่าง:
#   lib/**                ไลบรารีที่ vendor ไว้ — มีด่านของตัวเองแยกต่างหาก
#   tests/**              ชุดเทส ไม่ได้ถูกส่งไปถึงเบราว์เซอร์ของพนักงาน
#   playwright.config.js  ไฟล์ตั้งค่าของชุดเทส
#
# ถ้าวันหนึ่งย้ายโค้ดแอปไปไว้ใต้โฟลเดอร์ที่ชื่อขึ้นต้นเหมือนสามอันนี้ ต้องมาแก้ที่นี่
# และเทสจะเป็นตัวบอกว่าแก้แล้วยังตรงกับที่ตั้งใจอยู่ไหม
APP_PATHSPEC=('*.html' '*.js' ':(exclude)lib/**' ':(exclude)tests/**' ':(exclude)playwright.config.js')

# รายชื่อไฟล์แอปที่เปลี่ยนใน PR · ว่าง = PR นี้ไม่ได้แตะแอปเลย
app_changed_files() {
  git diff --name-only "$1...HEAD" -- "${APP_PATHSPEC[@]}"
}

# จำนวนบรรทัดที่เพิ่ม+ลบในไฟล์แอป — ใช้กับเพดานขนาด PR ของ agent
app_changed_lines() {
  git diff --numstat "$1...HEAD" -- "${APP_PATHSPEC[@]}" | awk '{a+=$1; d+=$2} END {print (a+d)+0}'
}

# ── การแตะไลบรารีที่ vendor ไว้ ────────────────────────────────────
# นับสองแบบแล้วรวมกัน เพราะไลบรารีอยู่ได้สองที่ระหว่างช่วงแยกไฟล์:
#   VENDOR_LONG = บรรทัดยาวผิดปกติในไฟล์แอป (ตอนที่ยังฝังอยู่ในบรรทัดเดียวกลางไฟล์)
#   VENDOR_LIB  = ไฟล์ใด ๆ ใน lib/ (ตอนที่แยกออกมาเป็นไฟล์แล้ว)
# INVARIANTS F2 นับทั้งสองแบบเป็น "แตะ vendor" เท่ากัน ทางผ่านคือ label vendor-change
# ตรวจจากความยาวบรรทัด ไม่ใช่เลขบรรทัด — เลขเลื่อนได้ แต่ความยาวไม่โกหก
# ⚠️ `|| true` ท้ายไปป์ไลน์ทั้งสองบรรทัดจำเป็น ห้ามลบ
# workflow รันด้วย `set -euo pipefail` · เมื่อ grep ไม่เจออะไร (ซึ่งคือกรณีปกติที่สุด)
# grep คืน 1 แล้ว pipefail ทำให้ทั้งไปป์ไลน์คืน 1 · การกำหนดค่าจากคำสั่งที่คืนค่าไม่ใช่ 0
# จะทำให้ errexit ฆ่า step ทิ้งทั้งที่ผลคือ "สะอาด" และไม่มีข้อความบอกว่าตายเพราะอะไร
# tests/guard-app-files.test.sh มีกรณีที่รันฟังก์ชันพวกนี้ใต้ `set -e` คุมไว้แล้ว
vendor_hits() {
  local base=$1
  VENDOR_LONG=$(git diff -U0 "$base...HEAD" -- '*.html' '*.js' | grep '^[+-]' | awk 'length($0)>20000' | wc -l || true)
  VENDOR_LIB=$(git diff --name-only "$base...HEAD" -- 'lib/**' | wc -l || true)
  VENDOR_LONG=$(printf '%s' "$VENDOR_LONG" | tr -d '[:space:]')
  VENDOR_LIB=$(printf '%s' "$VENDOR_LIB" | tr -d '[:space:]')
  echo $((VENDOR_LONG + VENDOR_LIB))
}

# ── การโหลดของจากเน็ต (INVARIANTS F2) ─────────────────────────────
# แอปต้องทำงานต่อได้เมื่อเน็ตหลุด การดึงของจากเน็ตทำให้พังเฉพาะตอนที่ต้องการใช้ที่สุด
#
# ครอบห้าทางที่ดึงของเข้ามาได้: <script src> · <link href> · import จาก URL ·
# import() แบบไดนามิก · importScripts() ของ worker
# `"?` ในรูปแบบทำให้จับ src=https:// แบบไม่ใส่อัญประกาศได้ด้วย
# และ `tr` แปลงอัญประกาศเดี่ยวเป็นคู่ก่อน รูปแบบเดียวจึงจับได้ทั้งสองแบบ
#
# การ fetch ตอนรันไปที่ Apps Script ใช้ URL ที่ผู้ใช้กรอกเอง ไม่ใช่ค่าคงที่ในโค้ด
# จึงไม่ติดด่านนี้ และห้ามทำให้ติด เพราะ F3 บังคับว่าห้าม hardcode URL นั้นอยู่แล้ว
NET_LOAD_RE='^\+.*(<script[^>]+src="?https?://|<link[^>]+href="?https?://|from "https?://|import\("https?://|importScripts\("https?://)'

# คืน 0 = พบการโหลดจากเน็ตที่เพิ่งเพิ่มเข้ามา · 1 = สะอาด
net_load_added() {
  git diff "$1...HEAD" -- '*.html' '*.js' | tr "'" '"' | grep -qE "$NET_LOAD_RE"
}
